INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(112330, 'ruRU', '', 'Когда ты впервые ступил на наши берега, я молился духам, спрашивая, можно ли доверять тебе. Помогая объединить наши племена, ты доказал, что являешься истинным другом нашего народа.', 24330),
(112331, 'ruRU', '', 'От имени племён Крутогорья я вверяю этот молот тебе и твоим союзникам. Пусть он безошибочно поражает сердце врага!', 24330),
(112332, 'ruRU', '', 'Духи шепчут, что наши судьбы переплетены, $n. Мой народ готов помочь тебе в войне против Легиона.', 24330),
(112334, 'ruRU', '', 'Для нас Молот Каз''горота всегда был символом единства, напоминанием о нашей гордой истории. Но в твоих руках он послужит ещё более великой цели.', 24330),
(112341, 'ruRU', '', 'Thala nar''valas.', 24330),
(112342, 'ruRU', '', 'Не забудь продвигать премиум-счёт!', 24330),
(112343, 'ruRU', '', 'Посмотри на всё это... надеюсь, ничего не пропадёт...', 24330),
(112344, 'ruRU', '', 'Если у вас пропали предметы, обратитесь в службу поддержки! Хе-хе-хе...', 24330),
(112350, 'ruRU', '', 'Ннгх... ХВАТИТ!!', 24330),
(112352, 'ruRU', '', 'Наш банк настолько надёжен, что у тебя возникнут проблемы даже с тем, чтобы забрать свои собственные вещи! Ха-ха!', 24330),
(112369, 'ruRU', '', 'Хмф! Ты совсем на него не похож! Ладно, давай посмотрим...', 24330),
(112370, 'ruRU', '', 'Похоже, у тебя его печать. Как тебе это удалось? Что ж, правила — это правила.', 24330),
(112371, 'ruRU', '', 'Передай этому здоровяку, что если он когда-нибудь захочет продолжить с того места, где мы остановились, пусть заглянет ко мне! Я здесь каждый день... в любой час!', 24330),
(112383, 'ruRU', '', 'Я чувствую их. Его воспоминания.', 24330),
(112387, 'ruRU', '', 'АААХХ!!', 24330),
(112389, 'ruRU', '', 'Прошу, $c, не медли. Я не могу представить мир без Кенария!', 24330),
(112390, 'ruRU', '', 'Что-то ужасное происходит, путник. Я это чувствую.', 24330),
(112391, 'ruRU', '', 'Какой вид, не правда ли?', 24330),
(112395, 'ruRU', '', 'A brief client scene happens here.', 24330),
(112398, 'ruRU', '', 'Я... я в порядке.', 24330),
(112409, 'ruRU', '', 'Ты обнаружишь, что время может быть весьма непостоянным.', 24330),
(112410, 'ruRU', '', 'Пусть волны времени обрушатся на тебя!', 24330),
(112411, 'ruRU', '', 'Я контролирую поле боя, а не ты!', 24330),
(112412, 'ruRU', '', 'Само время внемлет моему зову!', 24330),
(112413, 'ruRU', '', 'Помчишься сквозь время? Или окажешься в ловушке бесконечной вечности?', 24330),
(112414, 'ruRU', '', 'Нити времени подчиняются мне!', 24330),
(112415, 'ruRU', '', 'Потоки времени подвластны мне! Тебе не победить!', 24330),
(112423, 'ruRU', '', 'Очень смело с твоей стороны прийти аж сюда, $n. Мы перед тобой в долгу.', 24330),
(112449, 'ruRU', '', 'Извините, ребята, похоже, мы всё-таки пойдём по моему плану. Давайте обсудим детали.', 24330),
(112450, 'ruRU', '', '[CUT] Something incredibly powerful WAS there, but it expired long ago. Rather violently, from what I can tell.', 24330),
(112451, 'ruRU', '', '[CUT]What of your tests? Did you sense anything in Falanaar?', 24330),
(112452, 'ruRU', '', '[CUT] Magically speaking, the area is in chaos. With one notable exception...', 24330),
(112453, 'ruRU', '', '[CUT] Moonfall Retreat. Thank you, Valtrois. That will be all.', 24330),
(112463, 'ruRU', '', 'Боюсь, там тебе придётся действовать одному, пока не найдёшь Гарону. Меня узнают в одно мгновение так близко к территории Альянса.', 24330),
(112474, 'ruRU', '', 'Ты здесь, чтобы увести меня? Или ищешь лишь то, что осталось позади?', 24330),
(112475, 'ruRU', '', 'Мне велели стоять на страже, но за мной так никто и не вернулся. Я был не настолько силён, чтобы защитить это место... или, может, я просто был здесь слишком долго. Я уже не уверен.', 24330),
(112476, 'ruRU', '', 'Если хочешь, чтобы ритуал сработал, тебе нужен фокус. Я пытался не дать его чудовищам, но был слишком слаб.', 24330),
(112477, 'ruRU', '', 'Он лежит рядом с моим телом. Я... кажется, он держит меня здесь. Прошу, унеси его далеко отсюда. Возможно, тогда я наконец смогу отправиться домой.', 24330),
(112482, 'ruRU', '', 'Вантиру и мне нужна твоя помощь, чтобы отомстить...', 24330),
(112485, 'ruRU', '', 'Подойдёт кровь любого демона на Расколотых островах. Жаль, что я не иду с тобой.', 24330);
